2	//! functions that transitively call `crate::runner::MoonCommandRunner`'s
3	//! wasm-only `CommandRunner` impl (via `Workspace::load`/`MoonProjectLocator`),
4	//! and so can never actually execute inside a native `cargo-llvm-cov`
5	//! instrumented build (see `runner_pdk.rs`'s doc comment for the underlying
6	//! wasm-only-extern reason). Split into their own file so
7	//! `--ignore-filename-regex` can exclude it from coverage reports.
8	//!
9	//! Wire-level coverage (including their error paths) lives in
10	//! `tests/moon_wasm_sandbox.rs`, which drives the real compiled
11	//! `callisto-moon.wasm` module through an actual Extism/wasmtime host.
12	//!
13	//! `register_extension`, `define_extension_config`, `resolve_subcommand`,
14	//! and `format_graph_error_json` stay in `extension.rs`: none of them call
15	//! `MoonCommandRunner`, so they link and run fine natively under
16	//! `--features pdk` and are exercised by real native unit tests there.
17	
18	use crate::extension::{build_extension_output, format_graph_error_json, resolve_subcommand, ExecuteExtensionOutput};
19	use callisto_graph::locate::LocateError;
20	
21	#[cfg(feature = "pdk")]
22	pub fn execute_extension(input: moon_pdk_api::ExecuteExtensionInput) -> ExecuteExtensionOutput {
23	    use callisto_graph::commands::status::{status, StatusOptions};
24	
25	    // moon's real `ExecuteExtensionInput` nests the workspace root (and cwd)
26	    // inside `context: MoonContext` rather than as a flat `workspace_root`
27	    // field. `MoonContext::workspace_root` is a `VirtualPath`; `.to_path_buf()`
28	    // returns the (possibly WASI-virtualized) path, matching how the old flat
29	    // field was consumed below.
30	    let root = input.context.workspace_root.to_path_buf();
31	    let runner = crate::runner::MoonCommandRunner;
32	    let locator = match crate::locator::MoonProjectLocator::new(&runner, root.clone()) {
33	        Ok(loc) => loc,
34	        Err(e) => {
35	            let json_val = serde_json::json!({
36	                "schemaVersion": callisto_model::SCHEMA_VERSION,
37	                "error": { "code": "E_LOCATE", "message": e.to_string() }
38	            });
39	            return ExecuteExtensionOutput {
40	                report: json_val.clone(),
41	                rendered: e.to_string(),
42	                exit_code: 1,
43	            };
44	        }
45	    };
46	
47	    let ws = match callisto_graph::Workspace::load(root, &locator, &runner) {
48	        Ok(ws) => ws,
49	        Err(e) => {
50	            let json_val = format_graph_error_json(&e);
51	            return ExecuteExtensionOutput {
52	                report: json_val.clone(),
53	                rendered: e.to_string(),
54	                exit_code: 1,
55	            };
56	        }
57	    };
58	
59	    let subcmd = resolve_subcommand(&input.args);
60	
61	    match subcmd {
62	        "plan-publish" | "plan_publish" => {
63	            use callisto_graph::commands::publish::{plan_publish, PublishOptions};
64	            match plan_publish(&ws, &PublishOptions::default()) {
65	                Ok(report) => build_extension_output(serde_json::to_value(&report), 0),
66	                Err(e) => {
67	                    let json_val = format_graph_error_json(&e);
68	                    ExecuteExtensionOutput {
69	                        report: json_val.clone(),
70	                        rendered: e.to_string(),
71	                        exit_code: 1,
72	                    }
73	                }
74	            }
75	        }
76	        "validate" => {
77	            use callisto_graph::commands::validate::{validate, ValidateOptions};
78	            match validate(&ws, &ValidateOptions::default()) {
79	                Ok(report) => {
80	                    let exit_code = if report.ok { 0 } else { 1 };
81	                    build_extension_output(serde_json::to_value(&report), exit_code)
82	                }
83	                Err(e) => {
84	                    let json_val = format_graph_error_json(&e);
85	                    ExecuteExtensionOutput {
86	                        report: json_val.clone(),
87	                        rendered: e.to_string(),
88	                        exit_code: 1,
89	                    }
90	                }
91	            }
92	        }
93	        _ => {
94	            let opts = StatusOptions {
95	                strict: false,
96	                strict_graph: false,
97	            };
98	
99	            match status(&ws, &opts) {
100	                Ok(report) => {
101	                    let has_errors = report
102	                        .diagnostics
103	                        .iter()
104	                        .any(|d| d.severity == callisto_model::DiagnosticSeverity::Error);
105	                    let exit_code = if has_errors { 1 } else { 0 };
106	                    build_extension_output(serde_json::to_value(&report), exit_code)
107	                }
108	                Err(e) => {
109	                    let json_val = format_graph_error_json(&e);
110	                    ExecuteExtensionOutput {
111	                        report: json_val.clone(),
112	                        rendered: e.to_string(),
113	                        exit_code: 1,
114	                    }
115	                }
116	            }
117	        }
118	    }
119	}
