121	#[cfg(feature = "pdk")]
122	pub fn initialize_extension(
123	    input: moon_pdk_api::InitializeExtensionInput,
124	) -> Result<moon_pdk_api::InitializeExtensionOutput, LocateError> {
125	    use callisto_graph::commands::init::{init, InitOptions};
126	
127	    // moon's real `InitializeExtensionInput` (= `InitializePluginInput`) only
128	    // carries `context: MoonContext` — there is no `confirmed`/`yes` flag in
129	    // the real protocol (that was a callisto-only field on the old, locally
130	    // invented type). `InitOptions.yes` now gates `init`'s reconcile-apply
131	    // path (docs/00-design.md §18 Q5.4 mechanism 1): on a first run it has
132	    // no effect (scaffolding an absent `callisto.toml` is always a direct
133	    // write), and on a re-run it decides whether detected drift (e.g. a
134	    // newly-appeared ecosystem) is written or only reported. There is no
135	    // host-side prompt surface here to relay a diff through, so defaulting
136	    // to `true` — auto-applying reconcile drift — is the closest behavior-
137	    // preserving choice to the old unconditional-write behavior.
138	    let root = input.context.workspace_root.to_path_buf();
139	    let runner = crate::runner::MoonCommandRunner;
140	    let locator = crate::locator::MoonProjectLocator::new(&runner, root.clone())?;
141	    let ws = callisto_graph::Workspace::load(root, &locator, &runner).map_err(|e| LocateError::Graph(Box::new(e)))?;
142	    let opts = InitOptions { yes: true };
143	
144	    // Run callisto's existing init-detection/scaffolding logic. moon's real
145	    // `InitializeExtensionOutput` (= `InitializePluginOutput`) has no field
146	    // that can carry an arbitrary `InitReport` (schema version, config path,
147	    // diagnostics) — its shape is specifically for describing settings to
148	    // inject into moon's own toolchain config and prompts to ask the user,
149	    // neither of which callisto's `InitReport` maps onto cleanly. We still
150	    // run `init` for its side effects (scaffolding `callisto.toml` /
151	    // `.changeset`) and to propagate any error, but intentionally discard
152	    // the returned `InitReport` rather than inventing new output fields
153	    // moon doesn't expect. All fields below are therefore sensible defaults:
154	    // callisto has no hosted config/docs URL to advertise, no moon toolchain
155	    // settings to pre-populate, and no interactive prompts to ask.
156	    // This host surface has no `--dry-run` equivalent -- a moon extension
157	    // initialization is always a real scaffolding write -- so the permit is
158	    // granted unconditionally here rather than derived from a user flag. It
159	    // still goes through the one sanctioned constructor.
160	    let permit = callisto_model::ApplyPermit::granted_unless_dry_run(false);
161	    let _report = init(&ws, &opts, permit.as_ref()).map_err(|e| LocateError::Graph(Box::new(e)))?;
162	
163	    Ok(moon_pdk_api::InitializeExtensionOutput {
164	        config_url: None,
165	        default_settings: Default::default(),
166	        docs_url: None,
167	        prompts: Vec::new(),
168	    })
169	}
