1	use serde::{Deserialize, Serialize};
2	
3	use callisto_graph::locate::LocateError;
4	
5	// Real moon wire types, sourced from `moon_pdk_api` (moon v2.4.6-compatible,
6	// crate version 2.0.4). These are only usable/meaningful when compiling for
7	// the WASM plugin target, so they (and everything that consumes them) stay
8	// behind the `pdk` feature.
9	#[cfg(feature = "pdk")]
10	pub use moon_pdk_api::{
11	    DefineExtensionConfigOutput, ExecuteExtensionInput, InitializeExtensionInput, InitializeExtensionOutput,
12	    RegisterExtensionInput, RegisterExtensionOutput,
13	};
14	
15	/// Validates a moon version string against the range of moon versions this
16	/// extension supports.
17	///
18	/// NOTE: moon's real `RegisterExtensionInput` (see `moon_pdk_api::extension`)
19	/// only carries the extension's configured `id: Id` — it does not carry
20	/// moon's own version. moon negotiates plugin/host version compatibility out
21	/// of band (via the plugin manifest and `.moon/workspace.yml` `pluginVersion`
22	/// constraints), not over the `register_extension` wire call. This helper is
23	/// therefore kept as a standalone, independently-tested utility rather than
24	/// being wired into `register_extension`.
25	pub fn check_moon_version(version_str: &str) -> Result<(), LocateError> {
26	    if let Ok(ver) = semver::Version::parse(version_str) {
27	        let req = semver::VersionReq::parse(">=2.0.0, <3.0.0").unwrap();
28	        if req.matches(&ver) {
29	            return Ok(());
30	        }
31	    }
32	    Err(LocateError::IncompatibleMoonVersion {
33	        found: version_str.to_string(),
34	        required: ">=2.0.0, <3.0.0".to_string(),
35	    })
36	}
37	
38	#[cfg(feature = "pdk")]
39	pub fn register_extension(_input: RegisterExtensionInput) -> RegisterExtensionOutput {
40	    RegisterExtensionOutput {
41	        name: "callisto".to_string(),
42	        description: Some("Unified multi-ecosystem release manager for moon workspaces".to_string()),
43	        plugin_version: env!("CARGO_PKG_VERSION").to_string(),
44	    }
45	}
46	
47	/// Returns callisto's moon-config schema: deliberately near-empty, since
48	/// callisto's real settings live in `callisto.toml` (see `callisto-graph`'s
49	/// manifest loading), not in moon's own `.moon/workspace.yml`
50	/// `extensions.callisto.config` block. moon's real
51	/// `DefineExtensionConfigOutput` carries a `schematic::Schema` (a typed
52	/// schema-description tree used to render config docs/validation), not
53	/// arbitrary JSON Schema -- an empty `SchemaType::Struct` with no fields is
54	/// its equivalent of "no config keys to declare here".
55	#[cfg(feature = "pdk")]
56	pub fn define_extension_config() -> DefineExtensionConfigOutput {
57	    DefineExtensionConfigOutput {
58	        schema: schematic::Schema::structure(schematic_types::StructType::default()),
59	    }
60	}
61	
62	#[derive(Clone, Debug, Deserialize, Serialize)]
63	pub struct ExecuteExtensionOutput {
64	    pub report: serde_json::Value,
65	    pub rendered: String,
66	    pub exit_code: i32,
67	}
68	
69	#[cfg(feature = "pdk")]
70	pub(crate) fn format_graph_error_json(e: &callisto_graph::error::GraphError) -> serde_json::Value {
71	    serde_json::json!({
72	        "schemaVersion": callisto_model::SCHEMA_VERSION,
73	        "error": {
74	            "code": "E_GRAPH",
75	            "message": e.to_string(),
76	        }
77	    })
78	}
79	
80	/// Converts a serialization result into an [`ExecuteExtensionOutput`].
81	///
82	/// When `json_result` is `Ok`, the value and its pretty-printed rendering are
83	/// placed in the output with the supplied `exit_code`. When `json_result` is
84	/// `Err`, the serialization failure is surfaced as a structured error response
85	/// with `exit_code = 1` — preventing the host from receiving a silent
86	/// `null`/empty output that looks like success.
87	#[cfg(any(feature = "pdk", test))]
88	pub(crate) fn build_extension_output(
89	    json_result: serde_json::Result<serde_json::Value>,
90	    exit_code: i32,
91	) -> ExecuteExtensionOutput {
92	    match json_result {
93	        Ok(json_val) => {
94	            let rendered = serde_json::to_string_pretty(&json_val)
95	                .unwrap_or_else(|e| format!(r#"{{"error":"render failed: {e}"}}"#));
96	            ExecuteExtensionOutput {
97	                report: json_val,
98	                rendered,
99	                exit_code,
100	            }
101	        }
102	        Err(e) => {
103	            let msg = format!("internal serialization error: {e}");
104	            let json_val = serde_json::json!({
105	                "schemaVersion": callisto_model::SCHEMA_VERSION,
106	                "error": {
107	                    "code": "E_SERIALIZE",
108	                    "message": msg,
109	                }
110	            });
111	            let rendered = json_val.to_string();
112	            ExecuteExtensionOutput {
113	                report: json_val,
114	                rendered,
115	                exit_code: 1,
116	            }
117	        }
118	    }
119	}
120	
121	/// Resolves the subcommand `execute_extension` should dispatch to: the
122	/// first `args` element if present, otherwise `"status"`.
123	///
124	/// Pulled out as its own pure function (no `CommandRunner`/workspace I/O)
125	/// so this fallback can be unit-tested natively, without a real Extism
126	/// guest -- unlike `execute_extension` itself, which only links against a
127	/// real wasm32 Extism host (see `runner.rs`'s `pdk`-feature impl).
128	///
129	/// NOTE: resolves *which* name to dispatch on, doesn't validate it.
130	/// `execute_extension`'s `match` treats any unrecognized name
131	/// (`"plan-publish"`/`"plan_publish"`, `"validate"`) the same as no
132	/// subcommand -- silently falls back to `status`, same as empty `args`.
133	/// No distinct "unrecognized subcommand" error path exists yet.
134	#[cfg(feature = "pdk")]
135	pub(crate) fn resolve_subcommand(args: &[String]) -> &str {
136	    args.first().map(|s| s.as_str()).unwrap_or("status")
137	}
138	
139	// `execute_extension`/`initialize_extension` moved to `extension_pdk.rs` --
140	// both transitively call `crate::runner::MoonCommandRunner`'s wasm-only
141	// CommandRunner impl, so `cargo-llvm-cov` can never observe them executing
142	// natively. See that file's module doc comment.
143	
144	#[cfg(test)]
145	mod tests {
146	    use super::*;
147	
148	    #[test]
149	    fn test_moon_version_check() {
150	        assert!(check_moon_version("2.0.0").is_ok());
151	        assert!(check_moon_version("2.4.6").is_ok());
152	        assert!(check_moon_version("1.45.2").is_err());
153	        assert!(check_moon_version("3.0.0").is_err());
154	    }
155	
156	    /// `define_extension_config` is pure (no `CommandRunner`/wasm-host
157	    /// dependency) and safe to call natively, unlike its `pdk`-feature
158	    /// siblings that transitively construct a `MoonCommandRunner`. Asserts
159	    /// the same empty-struct shape `tests/moon_wasm_sandbox.rs`'s
160	    /// `define_extension_config_matches_moon_wire_protocol` already proves
161	    /// over the real wire, at the unit level.
162	    #[cfg(feature = "pdk")]
163	    #[test]
164	    fn define_extension_config_returns_empty_struct_schema() {
165	        let output = define_extension_config();
166	
167	        assert!(
168	            matches!(output.schema.ty, schematic_types::SchemaType::Struct(ref s) if s.fields.is_empty()),
169	            "expected an empty SchemaType::Struct, got {:?}",
170	            output.schema.ty
171	        );
172	    }
173	
174	    // NOTE on scope: `register_extension` is the only one of the three
175	    // `pdk`-feature plugin functions (`register_extension`,
176	    // `execute_extension`, `initialize_extension`) that is safe to call
177	    // directly from a native (non-wasm32) unit test. The other two
178	    // unconditionally construct a `crate::runner::MoonCommandRunner` and
179	    // pass it into `MoonProjectLocator`/`Workspace::load`; under the `pdk`
180	    // feature, `MoonCommandRunner`'s `CommandRunner` impl calls
181	    // `warpgate_pdk::exec`/`into_virtual_path`, which reference
182	    // Extism-host-only `extern "C"` imports (`_exec_command`,
183	    // `_to_virtual_path`, `_alloc`, ...) that plainly don't exist for native
184	    // linking. This isn't a theoretical concern: a native test that actually
185	    // calls `MoonCommandRunner::run` (or anything that transitively calls
186	    // it, which `execute_extension`/`initialize_extension` both do
187	    // unconditionally, regardless of which runtime branch would actually be
188	    // taken) fails at *link* time with "Undefined symbols for architecture
189	    // ...: _alloc, _exec_command, ...", not a runtime panic. Wire-level
190	    // coverage for `execute_extension`/`initialize_extension` (including
191	    // their error paths) therefore lives in
192	    // `tests/moon_wasm_sandbox.rs`, which drives the real compiled wasm
193	    // module through an actual Extism/wasmtime host. See also
194	    // `resolve_subcommand`, extracted specifically so at least
195	    // `execute_extension`'s dispatch fallback is natively unit-testable
196	    // without hitting this constraint.
197	    #[cfg(feature = "pdk")]
198	    #[test]
199	    fn register_extension_returns_well_formed_metadata_for_valid_input() {
200	        let input = RegisterExtensionInput {
201	            id: moon_pdk_api::Id::raw("callisto"),
202	        };
203	
204	        let output = register_extension(input);
