59	                    "-p",
60	                    "callisto-moon",
61	                    "--lib",
62	                    "--target",
63	                    "wasm32-wasip1",
64	                    "--features",
65	                    "pdk",
66	                    "--crate-type",
67	                    "cdylib",
68	                ])
69	                .current_dir(&root)
70	                .status()
71	                .expect("failed to invoke cargo rustc for callisto-moon.wasm fixture");
72	
73	            assert!(
74	                status.success(),
75	                "cargo rustc --target wasm32-wasip1 --features pdk --crate-type cdylib failed"
76	            );
77	        }
78	
79	        assert!(
80	            built.exists(),
81	            "expected wasm artifact at {} after build",
82	            built.display()
83	        );
84	
85	        // `find_wasm_file_with_name` treats `WARPGATE_PLUGINS_DIR` as a
86	        // pseudo workspace root and appends `wasm32-wasip1/<profile>/` (or
87	        // `target/wasm32-wasip1/<profile>/`) itself, so the staged file
